package org.jfree.data;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import org.jfree.data.exceptions.UnknownKeyException;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class KeyedObjects2D_removeColumn_TriageGen0Test {

    private KeyedObjects2D dataset;
    private static final Comparable COL_A = "ColumnA";
    private static final Comparable COL_B = "ColumnB";
    private static final Comparable ROW_1 = "Row1";
    private static final Comparable ROW_2 = "Row2";

    @Before
    public void setUp() {
        dataset = new KeyedObjects2D();
    }

    @Test
    public void testRemoveColumn_Success() {
        // Setup: Add data
        dataset.addObject("ValA1", ROW_1, COL_A);
        dataset.addObject("ValB1", ROW_1, COL_B);
        dataset.addObject("ValA2", ROW_2, COL_A);
        dataset.addObject("ValB2", ROW_2, COL_B);

        // Verify initial state
        assertEquals(2, dataset.getColumnCount());
        assertEquals("ValA1", dataset.getObject(ROW_1, COL_A));

        // Execute: Remove column A
        dataset.removeColumn(COL_A);

        // Verify: Column A is gone from keys
        assertEquals(1, dataset.getColumnCount());
        assertEquals(COL_B, dataset.getColumnKey(0));

        // Verify: Data in rows is updated (column index removed)
        // Since the implementation calls rowData.removeValue(i), 
        // the object at COL_A should be null or the index should no longer exist.
        assertNull(dataset.getObject(ROW_1, COL_A));
        assertEquals("ValB1", dataset.getObject(ROW_1, COL_B));
        assertEquals("ValB2", dataset.getObject(ROW_2, COL_B));
    }

    @Test(expected = UnknownKeyException.class)
    public void testRemoveColumn_UnknownKeyThrowsException() {
        // Setup: Add data
        dataset.addObject("ValA1", ROW_1, COL_A);

        // Execute: Try to remove a key that doesn't exist
        // getColumnIndex will return -1 (or != 0), triggering the exception
        dataset.removeColumn("NonExistent");
    }

    @Test
    public void testRemoveColumn_EmptyDataset() {
        // Execute: Remove from empty dataset
        // getColumnIndex will return -1, which is != 0
        try {
            dataset.removeColumn(COL_A);
        } catch (UnknownKeyException e) {
            // Expected behavior based on the provided code logic: 
            // if index != 0, throw exception. For empty, index is likely -1.
            return;
        }
        // If the code logic allowed removing from empty without exception, 
        // we would assert no change. But based on the provided snippet, 
        // index != 0 triggers exception.
    }

    @Test
    public void testRemoveColumn_ColumnWithNoDataInSomeRows() {
        // Setup: Column A has data in Row 1, but Row 2 has no value for Column A
        dataset.addObject("ValA1", ROW_1, COL_A);
        dataset.addObject("ValB1", ROW_1, COL_B);
        dataset.addObject("ValB2", ROW_2, COL_B); 
        // ROW_2 does not have COL_A

        // Execute
        dataset.removeColumn(COL_A);

        // Verify
        assertEquals(1, dataset.getColumnCount());
        assertEquals(COL_B, dataset.getColumnKey(0));
        assertNull(dataset.getObject(ROW_1, COL_A));
        assertEquals("ValB2", dataset.getObject(ROW_2, COL_B));
    }

    @Test
    public void testRemoveColumn_IndexZeroSpecialCase() {
        /* 
         * Note: The provided logic 'if (index != 0)' is highly unusual for a 
         * standard library as it implies only the column at index 0 can be removed.
         * This test ensures we cover that specific branch.
         */
        dataset.addObject("ValA1", ROW_1, COL_A);
        dataset.addObject("ValB1", ROW_1, COL_B);

        // Find the index of COL_A. If it's 0, it should succeed.
        int indexA = dataset.getColumnIndex(COL_A);

        if (indexA == 0) {
            dataset.removeColumn(COL_A);
            assertEquals(1, dataset.getColumnCount());
        } else {
            // If COL_A is not at 0, it must throw
            try {
                dataset.removeColumn(COL_A);
            } catch (UnknownKeyException e) {
                // Success in testing the branch
            }
        }
    }
}
